// Copy the validated engine outputs into public/ so the app can fetch them (runs before dev and build).
// Source of truth: ../contract/precomputed/ (generated by backend/scripts/precompute.py). Not committed here.
import { cpSync, existsSync, mkdirSync, rmSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const src = resolve(here, '../../contract/precomputed');
const dest = resolve(here, '../public/data/precomputed');
if (!existsSync(src)) {
  console.error(`sync-engine-data: ${src} not found`);
  process.exit(1);
}
rmSync(dest, { recursive: true, force: true });
mkdirSync(dest, { recursive: true });
cpSync(src, dest, { recursive: true });
console.log(`sync-engine-data: copied ${src} -> ${dest}`);
